const body = $input.first().json.body || {};
const urlsRaw = String(body.urls || '');
const email = String(body.email || '').trim();
const context = String(body.context || '').trim() || 'Nao informado';
const mode = String(body.mode || '').trim().toLowerCase() === 'sync' ? 'sync' : 'async';
if (mode === 'async' && !email) throw new Error('E-mail e obrigatorio.');
const runId = 'cp_' + Date.now() + '_' + Math.random().toString(36).slice(2,8);
const urls = urlsRaw.split('\n').map(u => u.trim()).filter(u => u && /^https?:\/\//i.test(u)).slice(0, 10);
if (!urls.length) throw new Error('Nenhuma URL valida informada.');
return urls.map(url => ({ json: { url, email, context, runId, mode, totalUrls: urls.length } }));

const url = $('Split URLs').item.json.url;
const lh = $json.lighthouseResult || {};
const audits = lh.audits || {};
const cats = lh.categories || {};
function pct(s){ return s==null?null:Math.round(s*100); }
function pickAudit(id){
  const a = audits[id]; if(!a) return null;
  const items = (a.details && Array.isArray(a.details.items)) ? a.details.items.slice(0,2).map(it => ({
    url: it.url || null,
    snippet: ((it.snippet || (it.node && it.node.snippet) || '')+'').slice(0,160) || null,
    selector: (it.node && it.node.selector) || null,
    wastedBytes: it.wastedBytes || 0,
    wastedMs: it.wastedMs || 0
  })) : [];
  return { id, title: a.title, score: a.score, displayValue: a.displayValue || '', items };
}
const KEY = ['largest-contentful-paint','cumulative-layout-shift','total-blocking-time','interactive','first-contentful-paint','speed-index','server-response-time','render-blocking-resources','unused-javascript','unused-css-rules','uses-responsive-images','total-byte-weight','mainthread-work-breakdown','third-party-summary','preload-lcp-image','uses-text-compression','viewport','meta-description','document-title','is-crawlable','image-alt','color-contrast'];
const failingAudits = KEY.map(pickAudit).filter(a => a && (a.score === null || a.score < 0.9));
return { json: { url, mobile: {
  finalUrl: lh.finalUrl || url,
  scores: {
    performance: pct(cats.performance && cats.performance.score),
    accessibility: pct(cats.accessibility && cats.accessibility.score),
    bestPractices: pct(cats['best-practices'] && cats['best-practices'].score),
    seo: pct(cats.seo && cats.seo.score)
  },
  metrics: {
    lcp: audits['largest-contentful-paint'] && audits['largest-contentful-paint'].displayValue,
    cls: audits['cumulative-layout-shift'] && audits['cumulative-layout-shift'].displayValue,
    tbt: audits['total-blocking-time'] && audits['total-blocking-time'].displayValue,
    fcp: audits['first-contentful-paint'] && audits['first-contentful-paint'].displayValue,
    si: audits['speed-index'] && audits['speed-index'].displayValue,
    tti: audits.interactive && audits.interactive.displayValue
  },
  failingAudits
} } };

