function pj(x){if(x&&typeof x==='object')return x;var z=String(x).match(/\{[\s\S]*\}/);if(!z)throw new Error('JSON não encontrado');return JSON.parse(z[0]);}
var d=pj(r);
var hc={'Crítico':'#dc2626','Atenção':'#d97706','Saudável':'#059669'}[d.overall_health]||'#6b7280';
var sc={'Crítica':'#dc2626','Alta':'#ea580c','Média':'#d97706','Baixa':'#059669'};
