if(x.type==='selector')return '<div style="background:#f3f4f6;border-left:3px solid #8b5cf6;padding:10px 12px;border-radius:6px;font-family:Consolas,monospace;font-size:12px"><div style="font-size:10px;color:#8b5cf6;font-weight:700;text-transform:uppercase;margin-bottom:4px">Elemento (CSS Selector)</div>'+s+'</div>'+(x.explanation?'<div style="font-size:12px;color:#6b7280;margin-top:6px;font-style:italic">'+e(x.explanation)+'</div>':'');
return '<div style="background:#1f2937;color:#e5e7eb;padding:10px 12px;border-radius:6px;font-family:Consolas,monospace;font-size:12px;overflow-x:auto;white-space:pre-wrap"><div style="font-size:10px;color:#fbbf24;font-weight:700;text-transform:uppercase;margin-bottom:4px">Trecho de codigo</div>'+s+'</div>'+(x.explanation?'<div style="font-size:12px;color:#6b7280;margin-top:6px;font-style:italic">'+e(x.explanation)+'</div>':'');}
function rf(t){var p=String(t||'').split('|').map(function(x){return x.trim();}).filter(Boolean);if(!p.length)return '';return '<ol style="margin:6px 0 0 0;padding-left:20px">'+p.map(function(x){return '<li style="font-size:13px;line-height:1.6;color:#1f2937;margin-bottom:4px">'+e(x)+'</li>';}).join('')+'</ol>';}
var fn=Array.isArray(d.prioritized_findings)?d.prioritized_findings:[];
var fh=fn.map(function(f){return '<div style="border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-bottom:14px"><div style="background:'+(sb[f.severity]||'#f9fafb')+';padding:14px 16px;border-bottom:1px solid #e5e7eb"><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px"><span style="background:'+(sc[f.severity]||'#6b7280')+';color:#fff;font-size:11px;font-weight:800;padding:3px 10px;border-radius:999px;text-transform:uppercase">#'+f.priority_rank+' &middot; '+e(f.severity||'Media')+'</span><span style="background:#fff;color:#374151;font-size:11px;font-weight:700;padding:3px 10px;border-radius:999px;border:1px solid #e5e7eb">'+e(f.category||'')+'</span>'+(Array.isArray(f.affected_devices)?f.affected_devices.map(function(v){return '<span style="background:#eef2ff;color:#4338ca;font-size:11px;font-weight:700;padding:3px 10px;border-radius:999px">'+e(v)+'</span>';}).join(''):'')+'</div><div style="font-size:16px;font-weight:800;color:#111827;line-height:1.3">'+e(f.title||'')+'</div></div><div style="padding:16px"><div style="font-size:13px;color:#374151;line-height:1.6;margin-bottom:14px">'+e(f.problem_description||'')+'</div>'+(Array.isArray(f.affected_urls)&&f.affected_urls.length?'<div style="font-size:11px;color:#6b7280;margin-bottom:14px"><strong>URLs afetadas:</strong> '+f.affected_urls.map(function(u){return e(u);}).join(', ')+'</div>':'')+'<div style="margin-bottom:14px"><div style="background:#eff6ff;border-left:3px solid #2563eb;padding:10px 12px;border-radius:6px;margin-bottom:10px"><div style="font-size:10px;color:#2563eb;font-weight:800;text-transform:uppercase;margin-bottom:4px">Impacto SEO</div><div style="font-size:13px;color:#1e3a8a;line-height:1.5">'+e(f.seo_impact||'')+'</div></div>'+(f.ads_impact?'<div style="background:#fef3c7;border-left:3px solid #d97706;padding:10px 12px;border-radius:6px"><div style="font-size:10px;color:#d97706;font-weight:800;text-transform:uppercase;margin-bottom:4px">Impacto Google Ads</div><div style="font-size:13px;color:#78350f;line-height:1.5">'+e(f.ads_impact)+'</div></div>':'')+'</div><div style="margin-bottom:14px"><div style="font-size:11px;color:#059669;font-weight:800;text-transform:uppercase;margin-bottom:4px">Como Corrigir</div>'+rf(f.how_to_fix)+'</div><div style="margin-bottom:10px"><div style="font-size:11px;color:#6b7280;font-weight:800;text-transform:uppercase;margin-bottom:6px">Exemplo Real</div>'+rx(f.real_example)+'</div><div style="display:flex;gap:14px;font-size:12px;color:#6b7280;padding-top:10px;border-top:1px solid #f3f4f6"><span><strong>Esforço:</strong> '+e(f.estimated_effort||'-')+'</span><span><strong>Ganho:</strong> '+e(f.expected_impact||'-')+'</span></div></div></div>';}).join('');
var ov=Array.isArray(d.pages_overview)?d.pages_overview:[];
var or=ov.map(function(p){return '<tr style="border-bottom:1px solid #f3f4f6"><td style="padding:8px;font-size:12px;color:#1f2937;word-break:break-all;max-width:240px">'+e(p.url||'')+'</td>'+sx(p.mobile_perf)+sx(p.desktop_perf)+sx(p.mobile_seo)+sx(p.desktop_seo)+sx(p.mobile_a11y)+sx(p.desktop_a11y)+'<td style="padding:8px;font-size:11px;color:#6b7280;font-family:Consolas,monospace">'+e(p.lcp_mobile||'-')+' / '+e(p.cls_mobile||'-')+'</td></tr>';}).join('');
var ins=Array.isArray(d.site_level_insights)?d.site_level_insights:[];
var ih=ins.length?'<ul style="margin:8px 0 0 0;padding-left:20px">'+ins.map(function(i){return '<li style="font-size:13px;line-height:1.6;color:#374151;margin-bottom:4px">'+e(i)+'</li>';}).join('')+'</ul>':'';
