:#6b7280;text-transform:uppercase">SEO M</th><th style="padding:10px;font-size:11px;color:#6b7280;text-transform:uppercase">SEO D</th><th style="padding:10px;font-size:11px;color:#6b7280;text-transform:uppercase">A11y M</th><th style="padding:10px;font-size:11px;color:#6b7280;text-transform:uppercase">A11y D</th><th style="padding:10px;font-size:11px;color:#6b7280;text-transform:uppercase">LCP/CLS M</th></tr></thead><tbody>'+or+'</tbody></table></div></div>':'')+(fh?'<div style="padding:0 32px 28px"><div style="font-size:18px;font-weight:800;margin-bottom:6px">Achados Priorizados</div><div style="font-size:12px;color:#6b7280;margin-bottom:16px">Ordenados pelo impacto em SEO orgânico e Google Ads. Comece pelo #1.</div>'+fh+'</div>':'')+(qh?'<div style="padding:0 32px 28px"><div style="font-size:16px;font-weight:800;margin-bottom:12px">Quick Wins</div>'+qh+'</div>':'')+'<div style="padding:18px 32px;background:#f9fafb;border-top:1px solid #e5e7eb;text-align:center;font-size:11px;color:#9ca3af">Gerado automaticamente pelo CorePulse Analyzer &middot; Run ID: '+e(m.runId)+'</div></div></body></html>';
